        text: "reflow는 비싸다. 한 요소의 크기가 바뀌면 브라우저는 ‘이 요소의 자식, 형제, 부모까지' 영향을 본다. 큰 페이지에서 작은 카드의 height가 변해도 전체 레이아웃을 다시 계산한다. contain은 ‘이 요소는 바깥에 영향을 주지 않는다'는 약속을 명시해 그 범위를 좁힌다."
